const dictionaries = { pt, en, es }
const localeTags: Record<Locale, string> = { pt: 'pt-BR', en: 'en-US', es: 'es-ES' }

function detectLocale(): Locale {
  const saved = localStorage.getItem('sensi-locale')
  if (saved === 'pt' || saved === 'en' || saved === 'es') return saved
  const languages = navigator.languages?.length ? navigator.languages : [navigator.language]
  for (const language of languages) {
    const normalized = language.toLowerCase()
    if (normalized === 'pt-br' || normalized.startsWith('pt-') || normalized === 'pt') return 'pt'
    if (normalized.startsWith('es')) return 'es'
    if (normalized.startsWith('en')) return 'en'
  }
  return 'en'
}

type I18nValue = {
  locale: Locale
  localeTag: string
  setLocale: (locale: Locale) => void
  t: (key: keyof typeof pt, params?: Params) => string
}

const I18nContext = createContext<I18nValue | null>(null)

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(detectLocale)
  useEffect(() => {
    document.documentElement.lang = localeTags[locale]
    document.title = dictionaries[locale]['meta.title']
  }, [locale])
  const value = useMemo<I18nValue>(() => ({
    locale,
    localeTag: localeTags[locale],
    setLocale: (next) => { localStorage.setItem('sensi-locale', next); setLocaleState(next) },
    t: (key, params) => {
      let text = dictionaries[locale][key] ?? en[key] ?? key
      for (const [name, replacement] of Object.entries(params ?? {})) text = text.replaceAll(`{${name}}`, String(replacement))
      return text
    },
  }), [locale])
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>
}

// The hook shares this module with its provider so consumers import one i18n surface.
// eslint-disable-next-line react-refresh/only-export-components
export function useI18n() {
  const context = useContext(I18nContext)
  if (!context) throw new Error('useI18n must be used inside I18nProvider')
  return context
}
